import os, socket
from http.server import BaseHTTPRequestHandler, HTTPServer

DB = os.environ["DB_HOST"]


def ping():
    with socket.create_connection((DB, 6379), timeout=2) as s:
        s.sendall(b"PING\r\n")
        return s.recv(16).decode().strip().lstrip("+")


class Api(BaseHTTPRequestHandler):
    def do_GET(self):
        try:
            body = f"API OK db={ping()}\n".encode()
        except OSError:
            body = b"API OK db=DOWN\n"
        self.send_response(200)
        self.end_headers()
        self.wfile.write(body)


HTTPServer(("0.0.0.0", 8000), Api).serve_forever()

import os
from http.server import BaseHTTPRequestHandler, HTTPServer


def load_key():
    try:
        with open("/run/secrets/api_key") as f:
            return f.read().strip()
    except OSError:
        return os.environ.get("API_KEY", "")


class Uplink(BaseHTTPRequestHandler):
    def do_GET(self):
        ok = load_key().startswith("kp_live_")
        self.send_response(200)
        self.end_headers()
        self.wfile.write(b"UPLINK AUTH OK\n" if ok else b"UPLINK NO KEY\n")


HTTPServer(("0.0.0.0", 8000), Uplink).serve_forever()

